preview.css:
.pop{position:relative;width:96px;height:96px}
.pop__icon{width:96px;height:96px;border-radius:26px;background:var(--p-color,var(--primary));color:#fff;font-size:44px;display:grid;place-items:center;animation:pop-in var(--p-cycle,2.4s) var(--p-ease,cubic-bezier(.34,1.56,.64,1)) infinite}
.pop__badge{position:absolute;top:-10px;right:-10px;width:30px;height:30px;border-radius:50%;background:var(--amber);color:#fff;font:700 14px/30px system-ui,sans-serif;text-align:center;animation:pop-in var(--p-cycle,2.4s) var(--p-ease,cubic-bezier(.34,1.56,.64,1)) var(--p-badge-delay,.25s) infinite}
@keyframes pop-in{0%{transform:scale(0) rotate(-20deg);opacity:0}18%{transform:scale(1) rotate(0);opacity:1}72%{transform:scale(1);opacity:1}86%,100%{transform:scale(0);opacity:0}}

.fu{width:200px;padding:14px;border-radius:14px;background:var(--surface);border:1px solid var(--line);box-shadow:0 10px 30px rgba(0,0,0,.08);animation:fade-up var(--p-cycle,3s) var(--p-ease,ease-out) infinite}
.fu__img{height:64px;border-radius:10px;background:linear-gradient(135deg,var(--primary),var(--blue))}
.fu__t{height:10px;margin-top:12px;border-radius:5px;background:var(--line)}
.fu__t--s{width:60%;margin-top:8px}
@keyframes fade-up{0%{opacity:0;transform:translateY(var(--p-distance,24px))}20%,78%{opacity:1;transform:translateY(0)}92%,100%{opacity:0;transform:translateY(-10px)}}

.stg{display:flex;align-items:flex-end;gap:12px;height:110px;margin:0;padding:0;list-style:none}
.stg li{width:28px;height:calc(50px + var(--i) * 14px);border-radius:8px 8px 3px 3px;background:var(--p-color,var(--primary));transform-origin:bottom;animation:stg var(--p-cycle,2.8s) var(--p-ease,cubic-bezier(.22,1,.36,1)) calc(var(--i) * var(--p-stagger,120ms)) infinite}
@keyframes stg{0%{transform:scaleY(0);opacity:0}22%,70%{transform:scaleY(1);opacity:1}82%,100%{transform:scaleY(0);opacity:0}}

.mr{position:relative;padding:8px 12px;overflow:hidden}
.mr__text{display:block;font:800 44px/1 system-ui,sans-serif;letter-spacing:-.04em;color:var(--text);clip-path:inset(0 100% 0 0);animation:mr-text var(--p-cycle,3s) cubic-bezier(.65,0,.35,1) infinite}
.mr__bar{position:absolute;inset:0 auto 0 0;width:var(--p-bar,18px);background:var(--p-color,var(--primary));transform:translateX(-30px);animation:mr-bar var(--p-cycle,3s) cubic-bezier(.65,0,.35,1) infinite}
@keyframes mr-text{0%,8%{clip-path:inset(0 100% 0 0)}40%,80%{clip-path:inset(0 0 0 0)}100%{clip-path:inset(0 100% 0 0)}}
@keyframes mr-bar{0%,8%{transform:translateX(-30px)}40%{transform:translateX(230px)}41%,100%{transform:translateX(-30px)}}

.tw{margin:0;font:600 var(--p-size,26px)/1.4 ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--text);white-space:nowrap;overflow:hidden;width:14ch;border-right:3px solid var(--p-color,var(--primary));animation:tw-type var(--p-cycle,3.2s) steps(14) infinite,tw-caret var(--p-blink,.7s) step-end infinite}
@keyframes tw-type{0%{width:0}60%,100%{width:14ch}}
@keyframes tw-caret{50%{border-color:transparent}}

.cu{display:flex;align-items:baseline;gap:10px;margin:0;color:var(--text)}
.cu__n{font:800 var(--p-size,56px)/1 system-ui,sans-serif;letter-spacing:-.04em;font-variant-numeric:tabular-nums;min-width:4.2em;text-align:right}
.cu__u{font:600 16px/1 system-ui,sans-serif;color:var(--muted)}

.mk{margin:0;font:600 22px/1.6 system-ui,sans-serif;color:var(--text)}
.mk span{background:linear-gradient(transparent calc(100% - var(--p-thick,45%)),rgba(245,164,85,.65) 0) no-repeat 0 0 / 0% 100%;background:linear-gradient(transparent calc(100% - var(--p-thick,45%)),color-mix(in srgb,var(--p-color,#f5a455) 65%,transparent) 0) no-repeat 0 0 / 0% 100%;padding:0 .1em;animation:mk var(--p-cycle,3s) var(--p-ease,ease-in-out) infinite}
@keyframes mk{0%,15%{background-size:0% 100%}40%,80%{background-size:100% 100%}95%,100%{background-size:0% 100%}}

.kw{display:flex;gap:.3em;margin:0;font:800 var(--p-size,34px)/1.3 system-ui,sans-serif;letter-spacing:-.03em;color:var(--text)}
.kw__roll{display:inline-block;height:1.3em;overflow:hidden;color:var(--p-color,var(--primary))}
.kw__list{display:flex;flex-direction:column;animation:kw var(--p-cycle,4.5s) var(--p-ease,cubic-bezier(.65,0,.35,1)) infinite}
.kw__list span{height:1.3em}
@keyframes kw{0%,25%{transform:translateY(0)}33%,58%{transform:translateY(-1.3em)}66%,91%{transform:translateY(-2.6em)}100%{transform:translateY(-3.9em)}}

.tg{position:relative;width:84px;height:46px;border-radius:23px;background:var(--line);animation:tg-track var(--p-cycle,3.2s) ease-in-out infinite}
.tg__knob{position:absolute;top:4px;left:4px;width:38px;height:38px;border-radius:50%;background:#fff;box-shadow:0 2px 6px rgba(0,0,0,.25);animation:tg-knob var(--p-cycle,3.2s) var(--p-bounce,cubic-bezier(.34,1.4,.64,1)) infinite}
@keyframes tg-track{0%,40%{background:var(--line)}50%,90%{background:var(--p-color,var(--primary))}100%{background:var(--line)}}
@keyframes tg-knob{0%,40%{transform:translateX(0)}50%,90%{transform:translateX(38px)}100%{transform:translateX(0)}}

.bp{position:relative;overflow:hidden;padding:16px 36px;border:0;border-radius:999px;background:var(--p-color,var(--primary));color:#fff;font:700 18px/1 system-ui,sans-serif;animation:bp-press var(--p-cycle,2.4s) ease-out infinite}
.bp__ripple{position:absolute;left:50%;top:50%;width:20px;height:20px;margin:-10px 0 0 -10px;border-radius:50%;background:rgba(255,255,255,.45);transform:scale(0);animation:bp-ripple var(--p-cycle,2.4s) ease-out infinite}
@keyframes bp-press{0%,28%{transform:scale(1)}34%{transform:scale(var(--p-press,.95))}44%,100%{transform:scale(1)}}
@keyframes bp-ripple{0%,30%{transform:scale(0);opacity:1}70%,100%{transform:scale(var(--p-ripple,14));opacity:0}}

.ts{position:absolute;left:50%;bottom:18px;display:flex;align-items:center;gap:10px;padding:12px 18px;border-radius:12px;background:var(--text);color:var(--bg);font:600 15px/1 system-ui,sans-serif;box-shadow:0 10px 30px rgba(0,0,0,.2);animation:ts var(--p-cycle,3.6s) var(--p-ease,cubic-bezier(.22,1,.36,1)) infinite}
.ts__icon{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--p-color,#2fb37a);color:#fff;font-size:13px}
@keyframes ts{0%{transform:translate(-50%,var(--p-distance,40px));opacity:0}12%,75%{transform:translate(-50%,0);opacity:1}88%,100%{transform:translate(-50%,var(--p-distance,40px));opacity:0}}

.sk{position:relative;width:220px;height:130px}
.sk__ph,.sk__real{position:absolute;inset:0;padding:12px;border-radius:14px;background:var(--surface);border:1px solid var(--line)}
.sk__img{height:56px;border-radius:10px;background:var(--line)}
.sk__t{height:10px;margin-top:12px;border-radius:5px;background:var(--line)}
.sk__t--s{width:55%;margin-top:8px}
.sk__ph>*{position:relative;overflow:hidden}
.sk__ph>*::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,var(--p-glow,.45)),transparent);transform:translateX(-100%);animation:sk-shine var(--p-shine,1.2s) linear infinite}
.sk__img--real{background:linear-gradient(135deg,var(--primary),var(--blue))}
.sk__title{margin:10px 0 0;font:700 13px/1.3 system-ui,sans-serif;color:var(--text)}
.sk__sub{margin:4px 0 0;font:500 11px/1.3 system-ui,sans-serif;color:var(--muted)}
.sk__ph{animation:sk-ph var(--p-cycle,4s) ease infinite}
.sk__real{opacity:0;animation:sk-real var(--p-cycle,4s) ease infinite}
@keyframes sk-shine{to{transform:translateX(100%)}}
@keyframes sk-ph{0%,55%{opacity:1}65%,92%{opacity:0}100%{opacity:1}}
@keyframes sk-real{0%,55%{opacity:0;transform:translateY(4px)}65%,92%{opacity:1;transform:translateY(0)}100%{opacity:0}}

.sf{width:240px;height:160px;overflow:hidden;border-radius:12px;background:var(--surface);border:1px solid var(--line)}
.sf__page{display:grid;gap:14px;padding:14px;animation:sf-scroll var(--p-cycle,5s) cubic-bezier(.65,0,.35,1) infinite}
.sf__sec{display:grid;gap:8px;padding:12px;border-radius:10px;background:var(--bg);border:1px solid var(--line);opacity:0;transform:translateY(var(--p-distance,16px));animation:sf-in var(--p-cycle,5s) var(--p-ease,ease-out) calc(var(--i) * var(--p-stagger,.9s)) infinite}
.sf__sec b{display:block;height:34px;border-radius:8px;background:linear-gradient(135deg,var(--primary),var(--blue));opacity:.85}
.sf__sec i{display:block;height:8px;width:70%;border-radius:4px;background:var(--line)}
@keyframes sf-scroll{0%,12%{transform:translateY(0)}70%,88%{transform:translateY(-200px)}100%{transform:translateY(0)}}
@keyframes sf-in{0%,6%{opacity:0;transform:translateY(var(--p-distance,16px))}16%,80%{opacity:1;transform:translateY(0)}92%,100%{opacity:0;transform:translateY(var(--p-distance,16px))}}

.sh{position:relative;width:240px;height:160px;overflow:hidden;border-radius:12px;background:var(--surface);border:1px solid var(--line)}
.sh__bar{position:absolute;z-index:1;inset:0 0 auto 0;display:flex;align-items:center;justify-content:space-between;height:44px;padding:0 14px;background:var(--surface);border-bottom:1px solid var(--line);animation:sh-bar var(--p-cycle,4.5s) cubic-bezier(.65,0,.35,1) infinite}
.sh__logo{width:60px;height:12px;border-radius:6px;background:var(--p-color,var(--primary))}
.sh__nav{width:80px;height:8px;border-radius:4px;background:var(--line)}
.sh__page{display:grid;gap:12px;padding:58px 14px 14px;animation:sh-scroll var(--p-cycle,4.5s) cubic-bezier(.65,0,.35,1) infinite}
.sh__page i{display:block;height:44px;border-radius:8px;background:var(--bg);border:1px solid var(--line)}
@keyframes sh-scroll{0%,15%{transform:translateY(0)}65%,85%{transform:translateY(-180px)}100%{transform:translateY(0)}}
@keyframes sh-bar{0%,15%{height:44px;box-shadow:none}30%,85%{height:var(--p-compact,32px);box-shadow:0 6px 18px rgba(0,0,0,var(--p-shadow,.12))}100%{height:44px;box-shadow:none}}

.sp{position:relative;width:240px;height:160px;overflow:hidden;border-radius:12px;background:var(--surface);border:1px solid var(--line)}
.sp__bar{position:absolute;z-index:1;top:0;left:0;height:var(--p-thick,4px);width:100%;background:var(--p-color,var(--primary));transform-origin:left;animation:sp-bar var(--p-cycle,4.5s) cubic-bezier(.65,0,.35,1) infinite}
.sp__page{display:grid;gap:10px;padding:18px 16px;animation:sp-scroll var(--p-cycle,4.5s) cubic-bezier(.65,0,.35,1) infinite}
.sp__page i{display:block;height:10px;border-radius:5px;background:var(--line)}
.sp__page i:nth-child(3n){width:70%}
@keyframes sp-scroll{0%,12%{transform:translateY(0)}72%,88%{transform:translateY(-120px)}100%{transform:translateY(0)}}
@keyframes sp-bar{0%,12%{transform:scaleX(0)}72%,88%{transform:scaleX(1)}100%{transform:scaleX(0)}}

.px{position:relative;width:280px;height:160px;overflow:hidden;border-radius:14px;background:linear-gradient(180deg,var(--bg),var(--surface))}
.px__sun{position:absolute;top:26px;right:50px;width:40px;height:40px;border-radius:50%;background:var(--p-sun,var(--amber));animation:px-move var(--p-cycle,4s) ease-in-out infinite alternate;--d:-8px}
.px__far{position:absolute;left:-20px;right:-20px;bottom:30px;height:90px;background:var(--blue);opacity:.35;clip-path:polygon(0 100%,15% 45%,30% 70%,48% 25%,62% 60%,78% 35%,100% 70%,100% 100%);animation:px-move var(--p-cycle,4s) ease-in-out infinite alternate;--d:-22px}
.px__near{position:absolute;left:-30px;right:-30px;bottom:-10px;height:70px;background:var(--p-near,var(--primary));border-radius:50% 50% 0 0;animation:px-move var(--p-cycle,4s) ease-in-out infinite alternate;--d:-50px}
@keyframes px-move{from{transform:translateY(0)}to{transform:translateY(calc(var(--d) * var(--p-depth,1)))}}

.gs{display:grid;place-items:center;width:260px;height:130px;border-radius:18px;background:linear-gradient(var(--p-angle,120deg),var(--p-c1,#6e4bff),var(--p-c2,#2563eb),var(--p-c3,#d97706),var(--p-c1,#6e4bff));background-size:300% 300%;animation:gs var(--p-cycle,7s) ease-in-out infinite alternate}
.gs span{font:800 28px/1 system-ui,sans-serif;letter-spacing:-.04em;color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.2)}
@keyframes gs{from{background-position:0% 50%}to{background-position:100% 50%}}

.fb{position:relative;display:grid;place-items:center;width:300px;height:170px;overflow:hidden;border-radius:16px;background:var(--surface)}
.fb__b{position:absolute;width:140px;height:140px;border-radius:50%;filter:blur(var(--p-blur,28px));opacity:.55}
.fb__b--1{left:-20px;top:-30px;background:var(--p-c1,var(--primary));animation:fb1 var(--p-cycle,6s) ease-in-out infinite alternate}
.fb__b--2{right:-30px;top:10px;background:var(--p-c2,var(--blue));animation:fb2 calc(var(--p-cycle,6s) + 1s) ease-in-out infinite alternate}
.fb__b--3{left:90px;bottom:-70px;background:var(--p-c3,var(--amber));animation:fb3 calc(var(--p-cycle,6s) + 2s) ease-in-out infinite alternate}
.fb__t{position:relative;font:800 34px/1 system-ui,sans-serif;letter-spacing:-.04em;color:var(--text)}
@keyframes fb1{to{transform:translate(50px,30px) scale(1.15)}}
@keyframes fb2{to{transform:translate(-40px,40px) scale(.9)}}
@keyframes fb3{to{transform:translate(-30px,-40px) scale(1.1)}}

.ls{position:relative;display:grid;align-content:end;gap:8px;width:240px;height:130px;padding:16px;overflow:hidden;border-radius:16px;background:linear-gradient(145deg,#1e1b2e,#2a2440);color:#fff;border:1px solid rgba(255,255,255,.12)}
.ls::after{content:'';position:absolute;inset:-40% -60%;background:linear-gradient(var(--p-angle,115deg),transparent calc(50% - var(--p-band,10%)),rgba(255,255,255,var(--p-glow,.35)) 50%,transparent calc(50% + var(--p-band,10%)));transform:translateX(-60%);animation:ls var(--p-cycle,3.2s) cubic-bezier(.65,0,.35,1) infinite}
.ls__badge{width:max-content;padding:4px 10px;border-radius:999px;background:var(--p-color,var(--primary));font:700 11px/1 system-ui,sans-serif;letter-spacing:.08em}
.ls__t{font:700 20px/1.2 system-ui,sans-serif}
@keyframes ls{0%,20%{transform:translateX(-60%)}60%,100%{transform:translateX(60%)}}
